    private String source;

    /** The sheet's proof kinds, comma separated: while set, a claim whose due is above the proof
     *  threshold needs at least one proof of each to be settled or approved; null when blank (none).
     *  Not dated. */
    @Column(name = "proof_kinds")
    private String proofKinds;

    /** The grade a person the quick-add bar adds, or an import line with a blank grade, is given;
     *  null when blank (A). Not dated. */
    @Column(name = "default_grade")
    private String defaultGrade;

    /** The grades retired on the sheet, comma separated in the order retired: none may be chosen
     *  for a new person or in an edit, while the people on one keep it; null when none. Not dated. */
    @Column(name = "retired_grades")
    private String retiredGrades;

    /** Whether a steward has archived the sheet: every change on it is refused. */
    @Column(name = "archived", nullable = false)
    private boolean archived;

    protected Sheet() {
    }

    public Sheet(String id, String createdBy, LocalDate today) {
        this.id = id;
        this.createdBy = createdBy;
        this.today = today;
    }

    /** A clone of the sheet under another id, created by a user: its today and every setting (its
     *  dated settings, policy date, period numbering, entry date, grace days, escalation gap, fiscal start month, pot, alert threshold and parent). It is
     *  not archived and has given no claim number yet, and has this sheet as its source. */
    public Sheet clonedTo(String id, String createdBy) {
        Sheet copy = new Sheet(id, createdBy, today);
        settings.forEach(d -> copy.settings.add(new DatedSetting(d.getKey(), d.getFrom(), d.getValue())));
        copy.policyDate = policyDate;
        copy.periodNumberingFrom = periodNumberingFrom;
        copy.entryDate = entryDate;
        copy.graceDays = graceDays;
        copy.escalateAfter = escalateAfter;
        copy.reviewSla = reviewSla;
        copy.maxOpen = maxOpen;
        copy.scoreMid = scoreMid;
        copy.scoreHigh = scoreHigh;
        copy.scoreLog = scoreLog;
        copy.fiscalStartMonth = fiscalStartMonth;
        copy.pot = pot;
        copy.alertThreshold = alertThreshold;
        copy.parent = parent;
        copy.source = this.id;
        copy.proofKinds = proofKinds;
        copy.defaultGrade = defaultGrade;
        copy.retiredGrades = retiredGrades;
        return copy;
    }

    public String getId() {
        return id;
    }
    }

    public void setProofKinds(String proofKinds) {
        this.proofKinds = proofKinds;
    }

    public String getDefaultGrade() {
        return defaultGrade;
    }

    public void setDefaultGrade(String defaultGrade) {
        this.defaultGrade = defaultGrade;
    }

    public String getRetiredGrades() {
        return retiredGrades;
    }

    /** Whether the grade has been retired on the sheet. */
    public boolean isGradeRetired(String grade) {
        return retiredGrades != null && Arrays.asList(retiredGrades.split(",")).contains(grade);
    }

    /** Retire the grade (it is not retired yet). */
    public void retireGrade(String grade) {
        retiredGrades = retiredGrades == null ? grade : retiredGrades + "," + grade;
    }

    public String getSource() {
        return source;
    }

    public String getParent() {
        return parent;
    }

import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets")
@Validated
public class SheetController {

    /** A sheet as the screen takes it: its id, its today, its floor with two decimals, its
     *  terms in days, its late percent with two decimals, its policy date (null when blank), and its cap with two decimals (null when none),
     *  the dated ones as in force on its today; and every value recorded for its dated settings,
     *  by key, each key's by from-date; whether it is archived; and its parent sheet's id (null when
     *  none), as it is now even when the sheet is shown as of a date; and its proof kinds, comma
     *  separated (null when none); and its default grade (null when blank: A); and its retired grades, in the
     *  order retired. */
    public record SheetView(String id, LocalDate today, String floor, int terms, String latePct, LocalDate policyDate,
            String cap, Map<String, List<DatedValue>> dated, boolean archived, String parent, String proofKinds,
            String defaultGrade, List<String> retiredGrades) {
        static SheetView of(Sheet sheet) {
            return of(sheet, sheet.getParent());
        }

        static SheetView of(Sheet sheet, String parent) {
            return new SheetView(sheet.getId(), sheet.getToday(), sheet.getFloor().toPlainString(), sheet.getTerms(),
                    sheet.getLatePct().setScale(2).toPlainString(), sheet.getPolicyDate(),
                    sheet.getCap() == null ? null : sheet.getCap().setScale(2).toPlainString(),
                    DatedValue.of(sheet.getDatedSettings()), sheet.isArchived(), parent, sheet.getProofKinds(),
                    sheet.getDefaultGrade(), SettingsService.retiredGrades(sheet));
        }
    }

    public record TodayChange(@NotNull LocalDate today) {
    }

    /** A clone as the screen submits it: the id of the sheet to clone this one to. */
    public record CloneForm(@NotBlank @Size(max = 100) @Pattern(regexp = "\\s*\\S+\\s*") String toSheetId) {
                + " key=" + PROOF_KINDS + " value=" + (value == null ? "" : value));
        return value;
    }

    /** Set the sheet's default grade (blank: A), the sheet created first if it was never loaded; not
     *  dated. A person the quick-add bar adds, and an import line with a blank grade, is given it;
     *  no one already on the sheet changes. Refused (422) when it is not one of the grades. Resolves
     *  to the grade as set (null: blank). */
    @Transactional
    public String setDefaultGrade(String sheetId, String user, String grade) {
        String value = grade.trim();
        if (!value.isEmpty() && !GRADES.contains(value)) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
                    "The default grade is one of " + String.join(", ", GRADES) + ", not " + value);
        }
        Sheet sheet = sheets.load(sheetId, user);
        sheets.lock(sheetId);
        sheet.setDefaultGrade(value.isEmpty() ? null : value);
        sheets.flush();
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user
                + " key=" + DEFAULT_GRADE + " value=" + value);
        return value.isEmpty() ? null : value;
    }

    /** Retire a grade on the sheet, the sheet created first if it was never loaded; not dated. It
     *  cannot be chosen for a new person or in an edit from then on; the people on it keep it.
     *  Refused (422) when it is not one of the grades, (409) when it is retired already. Resolves to
     *  the sheet's retired grades, in the order retired. */
    @Transactional
    public List<String> retireGrade(String sheetId, String user, String grade) {
        if (!GRADES.contains(grade)) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
                    "A grade is one of " + String.join(", ", GRADES) + ", not " + grade);
        }
        Sheet sheet = sheets.load(sheetId, user);
        sheets.lock(sheetId);
        if (sheet.isGradeRetired(grade)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Grade " + grade + " is retired already");
        }
        sheet.retireGrade(grade);
        sheets.flush();
        audit.recordOnCommit("GRADE_RETIRED sheet=" + sheetId + " by=" + user + " grade=" + grade);
        return retiredGrades(sheet);
    }

    /** The sheet's retired grades, in the order retired. */
    public static List<String> retiredGrades(Sheet sheet) {
        return sheet.getRetiredGrades() == null ? List.of() : List.of(sheet.getRetiredGrades().split(","));
    }

    /** The id of the sheet's parent; null when blank (none). */
