  }

  /** Re-read the signed-in user's locale (en when it cannot be read). */
export type UserLocale = (typeof LOCALES)[number];

interface SheetView {
  id: string;
  today: string;
  floor: string;
  terms: number;
  latePct: string;
  policyDate: string | null;
  cap: string | null;
  dated: DatedSettings;
  archived: boolean;
  parent: string | null;
  proofKinds: string | null;
  defaultGrade: string | null;
  retiredGrades: string[];
}

/** A value recorded for a dated setting: in force from its from-date (yyyy-mm-dd) until the next
 *  one of its key; null for none. */
export interface DatedValue {
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session, otherError } from '../../core/session';
import { Claim } from '../claims/claims-api';

export const GRADES = ['A', 'B', 'C'] as const;

/** A grade a person was given, and the first date (yyyy-mm-dd) it is in force; null for their first
 *  grade, in force from the beginning of time. */
export interface DatedGrade {
  grade: string;
export const TERMS_PATTERN = /^\d{1,4}$/;
/** A score threshold: a whole number, possibly below zero. */
export const SCORE_PATTERN = /^-?\d{1,6}$/;
/** A fiscal year start month: 1 to 12. */
export const FISCAL_START_MONTH_PATTERN = /^(0?[1-9]|1[0-2])$/;

/** The grades a person can hold, each of which can have terms of its own. */
export const GRADES = ['A', 'B', 'C'] as const;

export interface Settings {
  /** Two decimals, as the server formats it; null when there is no limit. */

  /** Add a void reason; resolves to the sheet's void reasons with it. */
  addVoidReason(sheetId: string, reason: string): Promise<string[]> {
    return firstValueFrom(
      this.http.post<string[]>(`${this.url(sheetId)}/void-reasons`, { reason }, { headers: this.headers() }),
    );
  }

  /** Retire a grade; resolves to the sheet's retired grades with it. */
  retireGrade(sheetId: string, grade: string): Promise<{ retiredGrades: string[] }> {
    return firstValueFrom(
      this.http.post<{ retiredGrades: string[] }>(`${this.url(sheetId)}/grades/retire`, { grade }, { headers: this.headers() }),
    );
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}`;
  }

  private headers(): Record<string, string> {
    return { 'X-User': this.session.user() ?? '' };

